[project]
name = "underdogs-tarvo"
version = "0.1.0"
description = "Solução de fechamento financeiro automatizado com rastreabilidade total para Tarvo Pagamentos - Desafio Barte AI"
readme = "README.md"
requires-python = ">=3.11"
authors = [
    { name = "Pablo Carvalho", email = "pablo@example.com" }
]
dependencies = [
    "pandas>=2.2.0",
    "openpyxl>=3.1.2",
    "ofxparse>=0.21",
    "python-dateutil>=2.9.0",
    "pydantic>=2.7.0",
    "rich>=13.7.0",
    "typer>=0.12.0",
]

[project.optional-dependencies]
dev = [
    "pytest>=8.0.0",
    "ruff>=0.4.0",
    "mypy>=1.10.0",
    "pandas-stubs",
    "types-openpyxl",
]

[build-system]
requires = ["hatchling"]
build-backend = "hatchling.build"

[tool.hatch.build.targets.wheel]
packages = ["src"]

[tool.ruff]
line-length = 100
target-version = "py312"

[tool.pytest.ini_options]
testpaths = ["tests"]
python_files = ["test_*.py"]
const { spawnSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const rootDir = path.resolve(__dirname, '..');
const isWin = process.platform === 'win32';

// Detecta o executavel python do ambiente virtual local se existir
const venvPython = isWin
  ? path.join(rootDir, '.venv', 'Scripts', 'python.exe')
  : path.join(rootDir, '.venv', 'bin', 'python');

const pythonBin = fs.existsSync(venvPython) ? venvPython : (isWin ? 'python' : 'python3');
const args = process.argv.slice(2);

const res = spawnSync(pythonBin, args, { stdio: 'inherit', cwd: rootDir });

// Falha ao iniciar o processo (ex: python ausente) nao pode virar sucesso
if (res.error) {
  console.error(`Falha ao executar ${pythonBin}: ${res.error.message}`);
  process.exit(1);
}

// Processo morto por sinal (ex: OOM kill) tem status null
if (res.signal) {
  console.error(`${pythonBin} encerrado pelo sinal ${res.signal}`);
  process.exit(1);
}

process.exit(res.status ?? 1);
ok

